import {STORAGE_KEY,emptyLedger,localDate,validMonth,validateLedger,saveTransaction,deleteTransaction,saveCategory,monthlySummary,persistLedger,money,amountInput} from './ledger.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette=['#244d83','#c97447','#328f9b','#8d79ad','#d4a942','#7490b6','#778c74','#bc7885'];
let ledger=emptyLedger(),month=localDate().slice(0,7),shareType='expense',categoryType='expense',editingId=null,deletingId=null,pendingRestore=null,rawData=null,blocked=false,toastTimer;
const form=$('#entry-form');
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function storageWarning(message){$('#storage-warning').textContent=message;$('#storage-warning').hidden=!message;}
function load(){try{rawData=localStorage.getItem(STORAGE_KEY);ledger=rawData===null?emptyLedger():validateLedger(JSON.parse(rawData));blocked=false;storageWarning('');}catch(error){blocked=true;storageWarning(rawData!==null?'账本数据无法读取，原始数据已保留。请在“账本备份”中下载原始数据，或选择有效备份恢复。':'浏览器存储暂时不可用，无法保存账本。请检查浏览器设置后刷新重试。');}}
function current(){if(blocked)throw Error('当前账本无法读取，请先从有效备份恢复');const latest=localStorage.getItem(STORAGE_KEY);if(latest!==rawData){ledger=latest===null?emptyLedger():validateLedger(JSON.parse(latest));rawData=latest;render();}return ledger;}
function commit(next){let clean;try{clean=persistLedger(localStorage,next);}catch(error){if(error.name==='QuotaExceededError'||error.name==='SecurityError')throw Error('保存失败：浏览器存储不可用或空间不足。输入已保留，请重试。');throw error;}ledger=clean;rawData=JSON.stringify(clean);blocked=false;storageWarning('');render();}
function render(){const summary=monthlySummary(ledger,month);$('#month').value=month;$('#income-total').textContent=money(summary.incomeCents);$('#expense-total').textContent=money(summary.expenseCents);$('#balance-total').textContent=money(summary.balanceCents);$('#record-count').textContent=`本月 ${summary.count} 笔记录`;$('#ledger-count').textContent=`${summary.count} 笔`;$('#prev-month').disabled=month==='0001-01';$('#next-month').disabled=month==='9999-12';$('#add').disabled=blocked;$('#categories-open').disabled=blocked;renderShare(summary);renderTrend(summary);renderLedger();}
function renderShare(summary){
  for(const type of ['income','expense']){$('#share-'+type).classList.toggle('active',shareType===type);$('#share-'+type).setAttribute('aria-pressed',String(shareType===type));}
  const total=summary[shareType+'Cents'],label=shareType==='expense'?'支出':'收入',categories=summary.categories.filter(c=>c.type===shareType);
  if(!total){$('#category-chart').innerHTML=`<div class="empty-ring"><strong>${money(0)}</strong><span>本月${label}</span></div><div class="empty-chart">暂无${label}记录</div>`;return;}
  let offset=0;const arcs=categories.map((c,i)=>{const length=c.amountCents/total*100,segment=`<circle cx="90" cy="90" r="73" fill="none" stroke="${palette[i%palette.length]}" stroke-width="18" pathLength="100" stroke-dasharray="${length} ${100-length}" stroke-dashoffset="${-offset}"><title>${escape(c.name)}：${money(c.amountCents)}</title></circle>`;offset+=length;return segment;}).join('');
  $('#category-chart').innerHTML=`<div class="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label="${label}分类占比">${arcs}</svg><div class="donut-label"><strong>${money(total)}</strong><span>本月${label}</span></div></div><div class="category-stats">${categories.map((c,i)=>`<div class="category-stat"><i style="background:${palette[i%palette.length]}"></i><span class="stat-name">${escape(c.name)}</span><div><strong>${money(c.amountCents)}</strong><small>${(c.amountCents/total*100).toFixed(1)}%</small></div></div>`).join('')}</div>`;
}
function axis(cents){const v=cents/100;return v>=100000000?(v/100000000).toFixed(1)+'亿':v>=10000?(v/10000).toFixed(1)+'万':v>=1000?(v/1000).toFixed(1)+'千':v.toFixed(v<10?1:0);}
function renderTrend(summary){
  const rows=summary.daily,maximum=Math.max(...rows.map(d=>Math.max(d.incomeCents,d.expenseCents)),100),top=maximum*1.15,x=i=>48+i/(rows.length-1)*442,y=v=>170-v/top*140;
  const lines=['income','expense'].map(type=>`<polyline fill="none" stroke="${type==='income'?'#087f70':'#c65b35'}" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" points="${rows.map((d,i)=>`${x(i)},${y(d[type+'Cents'])}`).join(' ')}"/>`).join('');
  const grid=Array.from({length:4},(_,i)=>{const value=top*i/3;return `<line x1="48" x2="490" y1="${y(value)}" y2="${y(value)}" stroke="#edf1f6"/><text x="42" y="${y(value)+4}" text-anchor="end">${axis(value)}</text>`;}).join('');
  const dates=rows.map((d,i)=>`<rect data-day="${i}" x="${x(i)-7}" y="20" width="14" height="155" fill="transparent" tabindex="0" role="button" aria-label="${d.date} 收入${money(d.incomeCents)}，支出${money(d.expenseCents)}"><title>${d.date} 收入 ${money(d.incomeCents)} / 支出 ${money(d.expenseCents)}</title></rect>${i===0||i===rows.length-1||(i+1)%7===0?`<text x="${x(i)}" y="195" text-anchor="middle">${i+1}日</text>`:''}`).join('');
  $('#trend-chart').innerHTML=`<svg viewBox="0 0 510 210" role="group" aria-label="每日收支趋势，金额单位元">${grid}${lines}${dates}</svg>${summary.count?'':'<p class="chart-caption">本月暂无记录，记一笔开始查看趋势</p>'}`;$('#trend-detail').textContent='选择图中的日期，查看当天收支';
  const detail=element=>{const d=rows[Number(element.dataset.day)];$('#trend-detail').textContent=`${d.date}　收入 ${money(d.incomeCents)}　支出 ${money(d.expenseCents)}`;};
  $$('#trend-chart [data-day]').forEach(el=>{el.addEventListener('pointerenter',()=>detail(el));el.addEventListener('click',()=>detail(el));el.addEventListener('focus',()=>detail(el));el.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();detail(el);}});});
}
function renderLedger(){
  const records=ledger.transactions.filter(t=>t.date.startsWith(month+'-')).map((t,index)=>({...t,index})).sort((a,b)=>b.date.localeCompare(a.date)||b.index-a.index);
  if(!records.length){$('#ledger').innerHTML=`<div class="ledger-empty"><span class="empty-ledger-icon" aria-hidden="true">＋</span><h3>${blocked?'账本暂时无法读取':'从第一笔开始'}</h3><p>${blocked?'打开账本备份，查看恢复选项':'一杯咖啡、一份工资<br>生活里的每笔收支，都值得记下来'}</p><button class="button primary" id="empty-add" ${blocked?'disabled':''}>记一笔</button></div>`;$('#empty-add').onclick=()=>openEntry();return;}
  const groups=new Map();for(const t of records){if(!groups.has(t.date))groups.set(t.date,[]);groups.get(t.date).push(t);}
  $('#ledger').innerHTML=[...groups].map(([date,items])=>{const total=type=>items.filter(t=>t.type===type).reduce((sum,t)=>sum+t.amountCents,0);return `<div class="day-group"><div class="day-head"><strong>${date===localDate()?'今天 · ':''}${date}</strong><span class="day-totals"><span>收 ${money(total('income'))}</span><span>支 ${money(total('expense'))}</span></span></div>${items.map(t=>{const category=ledger.categories.find(c=>c.id===t.categoryId);return `<div class="entry-row"><span class="entry-badge ${t.type}">${escape(category.name.slice(0,1))}</span><div class="entry-content"><div class="entry-category">${escape(category.name)}</div>${t.note?`<div class="entry-note">${escape(t.note)}</div>`:''}</div><div class="entry-right"><div class="entry-amount ${t.type}"><span class="sr-only">${t.type==='income'?'收入':'支出'}</span>${t.type==='income'?'+':'−'}${money(t.amountCents)}</div><div class="entry-actions"><button data-edit="${t.id}" aria-label="编辑${escape(category.name)} ${money(t.amountCents)}">编辑</button><button data-delete="${t.id}" aria-label="删除${escape(category.name)} ${money(t.amountCents)}">删除</button></div></div></div>`;}).join('')}</div>`;}).join('');
  $$('[data-edit]').forEach(b=>b.onclick=()=>openEntry(b.dataset.edit));$$('[data-delete]').forEach(b=>b.onclick=()=>{deletingId=b.dataset.delete;$('#delete-error').textContent='';$('#confirm-dialog').showModal();});
}
function categoriesForEntry(selected){const type=form.elements.type.value;form.elements.categoryId.innerHTML=ledger.categories.filter(c=>c.type===type).map(c=>`<option value="${c.id}">${escape(c.name)}</option>`).join('');if(selected)form.elements.categoryId.value=selected;}
function openEntry(id=null){try{current();}catch(error){notify(error.message);return;}const t=ledger.transactions.find(t=>t.id===id);editingId=id;form.reset();$('#entry-title').textContent=id?'编辑记录':'记一笔';$('#entry-error').textContent='';form.elements.type.value=t?.type||'expense';categoriesForEntry(t?.categoryId);form.elements.amount.value=t?amountInput(t.amountCents):'';form.elements.date.value=t?.date||localDate();form.elements.note.value=t?.note||'';$('#entry-dialog').showModal();form.elements.amount.focus();}
form.addEventListener('change',event=>{if(event.target.name==='type')categoriesForEntry();});
form.addEventListener('submit',event=>{event.preventDefault();try{const result=saveTransaction(current(),{type:form.elements.type.value,amount:form.elements.amount.value,categoryId:form.elements.categoryId.value,date:form.elements.date.value,note:form.elements.note.value},editingId);commit(result.ledger);month=result.record.date.slice(0,7);render();$('#entry-dialog').close();notify(editingId?'记录已更新':'已记下一笔');}catch(error){$('#entry-error').textContent=error.message;}});
$('#add').onclick=()=>openEntry();$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#confirm-delete').onclick=()=>{try{commit(deleteTransaction(current(),deletingId));$('#confirm-dialog').close();notify('记录已删除');}catch(error){$('#delete-error').textContent=error.message;}};
function changeMonth(value){if(!validMonth(value)){notify('请选择有效月份');$('#month').value=month;return;}month=value;render();}
$('#month').onchange=event=>changeMonth(event.target.value);
function moveMonth(delta){const [year,m]=month.split('-').map(Number),absolute=(year-1)*12+(m-1)+delta;if(absolute<0||absolute>=9999*12)return;changeMonth(`${String(Math.floor(absolute/12)+1).padStart(4,'0')}-${String(absolute%12+1).padStart(2,'0')}`);}
$('#prev-month').onclick=()=>moveMonth(-1);$('#next-month').onclick=()=>moveMonth(1);$('#this-month').onclick=()=>changeMonth(localDate().slice(0,7));
for(const type of ['expense','income'])$('#share-'+type).onclick=()=>{shareType=type;renderShare(monthlySummary(ledger,month));};
function renderCategories(){
  $$('[data-category-type]').forEach(b=>{b.classList.toggle('active',b.dataset.categoryType===categoryType);b.setAttribute('aria-pressed',String(b.dataset.categoryType===categoryType));});
  $('#category-list').innerHTML=ledger.categories.filter(c=>c.type===categoryType).map(c=>`<form class="category-row" data-category-id="${c.id}" novalidate><label class="sr-only" for="rename-${c.id}">分类名称</label><input id="rename-${c.id}" maxlength="20" value="${escape(c.name)}" required><button class="button quiet" type="submit">保存名称</button></form>`).join('');
  $$('.category-row').forEach(row=>row.onsubmit=event=>{event.preventDefault();try{commit(saveCategory(current(),categoryType,row.querySelector('input').value,row.dataset.categoryId));$('#category-error').textContent='';renderCategories();notify('分类名称已更新');}catch(error){$('#category-error').textContent=error.message;}});
}
$('#categories-open').onclick=()=>{try{current();renderCategories();$('#category-error').textContent='';$('#categories-dialog').showModal();}catch(error){notify(error.message);}};
$$('[data-category-type]').forEach(b=>b.onclick=()=>{categoryType=b.dataset.categoryType;$('#category-error').textContent='';renderCategories();});
$('#category-form').onsubmit=event=>{event.preventDefault();try{commit(saveCategory(current(),categoryType,$('#category-name').value));$('#category-name').value='';$('#category-error').textContent='';renderCategories();notify('分类已新增');}catch(error){$('#category-error').textContent=error.message;}};
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function clearRestore(){pendingRestore=null;$('#restore-preview').hidden=true;$('#import-file').value='';$('#backup-error').textContent='';}
$('#backup-open').onclick=()=>{clearRestore();$('#backup-text-label').hidden=true;$('#backup-text').value='';$('#show-backup').disabled=blocked;$('#export').disabled=blocked;$('#export-raw').hidden=!blocked||rawData===null;$('#backup-dialog').showModal();};
$('#show-backup').onclick=()=>{try{$('#backup-text').value=JSON.stringify(validateLedger(current()),null,2);$('#backup-text-label').hidden=false;$('#backup-text').focus();$('#backup-text').select();}catch(error){$('#backup-error').textContent=error.message;}};
$('#export').onclick=()=>{try{download(JSON.stringify(validateLedger(current()),null,2),`随手账备份-${localDate()}.json`);notify('已生成备份，请查看浏览器下载');}catch(error){$('#backup-error').textContent=error.message;}};
$('#export-raw').onclick=()=>download(rawData,`随手账原始数据-${localDate()}.json`);
$('#import-file').onchange=async event=>{pendingRestore=null;$('#restore-preview').hidden=true;$('#backup-error').textContent='';const file=event.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('备份文件过大，请选择20MB以内的文件');const clean=validateLedger(JSON.parse(await file.text()));pendingRestore=clean;$('#restore-summary').textContent=`有效备份：${clean.transactions.length} 笔记录，${clean.categories.length} 个分类。确认后将替换当前全部数据。`;$('#restore-preview').hidden=false;}catch(error){$('#backup-error').textContent=error instanceof SyntaxError?'无法读取 JSON 备份文件':error.message;}};
$('#cancel-restore').onclick=clearRestore;
$('#confirm-restore').onclick=()=>{if(!pendingRestore)return;try{commit(pendingRestore);clearRestore();$('#backup-dialog').close();notify('账本已恢复');}catch(error){$('#backup-error').textContent=error.message;}};
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY||event.key===null){load();render();notify('账本已在其他页面更新');}});
function connectivity(){if(!navigator.onLine)$('#offline-status').textContent='当前离线 · 记账保存在本机';}
window.addEventListener('offline',connectivity);window.addEventListener('online',()=>$('#offline-status').textContent='数据保存在本机');
load();render();connectivity();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;$('#offline-status').textContent=navigator.onLine?'离线资源已就绪 · 可离线记账':'当前离线 · 可继续记账';}).catch(()=>$('#offline-status').textContent='本地记账可用 · 离线资源未就绪');}
const context=document.modelContext;
if(context?.registerTool){
  const lifecycle=new AbortController(),register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(error=>console.info('WebMCP registration unavailable',error.message));}catch(error){console.info('WebMCP registration unavailable',error.message);}};
  register({name:'get_monthly_summary',title:'读取月度统计',description:'读取当前浏览器账本中指定月份的收支、分类目录和每日趋势。金额单位为分。',inputSchema:{type:'object',properties:{month:{type:'string',pattern:'^[0-9]{4}-(0[1-9]|1[0-2])$'}},required:['month'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){const source=current();return {...monthlySummary(source,input.month),categoryCatalog:source.categories};}});
  register({name:'add_transaction',title:'新增收支记录',description:'立即保存一笔收入或支出到当前浏览器账本。金额为人民币元的十进制字符串，分类ID可从月度统计工具的分类目录取得。',inputSchema:{type:'object',properties:{type:{type:'string',enum:['income','expense']},amount:{type:'string'},categoryId:{type:'string'},date:{type:'string'},note:{type:'string',maxLength:500}},required:['type','amount','categoryId','date'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){const result=saveTransaction(current(),{...input,note:input.note??''});commit(result.ledger);month=result.record.date.slice(0,7);render();return {id:result.record.id,saved:true};}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
